from django.db import models
from accounts.models import AuthorProfile
class Book(models.Model):
    book_id=models.CharField(max_length=64,unique=True); author=models.ForeignKey(AuthorProfile,on_delete=models.CASCADE,related_name='books'); title=models.CharField(max_length=300); isbn=models.CharField(max_length=64,null=True,blank=True); genre=models.CharField(max_length=100,blank=True); publication_date=models.DateField(null=True,blank=True); status=models.CharField(max_length=100); mrp=models.DecimalField(max_digits=12,decimal_places=2,null=True,blank=True); author_royalty_per_copy=models.DecimalField(max_digits=12,decimal_places=2,null=True,blank=True); total_copies_sold=models.PositiveIntegerField(default=0); total_royalty_earned=models.DecimalField(max_digits=14,decimal_places=2,default=0); royalty_paid=models.DecimalField(max_digits=14,decimal_places=2,default=0); royalty_pending=models.DecimalField(max_digits=14,decimal_places=2,default=0); last_royalty_payout_date=models.DateField(null=True,blank=True); print_partner=models.CharField(max_length=200,null=True,blank=True); available_on=models.JSONField(default=list,blank=True); created_at=models.DateTimeField(auto_now_add=True); updated_at=models.DateTimeField(auto_now=True)
    def __str__(self): return self.title
